"""The 5M model: ft3's CausalPatchDecoder with tidemark's loss mask (tideforge/model/ft3_model.py, generated by
tools/port_model.py), built from the recipe's cfg.

build(cfg, options) is the model-option hook (EXPERIMENTS.md: M1 known-covariate attention over the whole window, M2 static
embedding, M3 more lanes). The options live in the cfg (recipe.ft3_cfg writes them, so every checkpoint records them); a cfg
without them (ft3_main.pt) is all "off". Options:
  known_attn       off | mask        M1 (tideforge/model/m1.py, owner OK 2026-10-29); off = the port itself, bit-exact
  known_lookahead  None | K >= 1     M1's band: a token never sees a known value beyond K + 1 patches ahead (None = whole segment)
Any other option raises, so a config cannot silently ask for an unbuilt model.

load(path, device) is the strict checkpoint loader for every scorer (the probes' Ft3 / M5 adapters, devscore, finish), and
use_loader() swaps it in for third_party's score_ft3.load_ft3 while tidemark's fev / TIME scorer runs (tideforge.eval.score), so
an M1 checkpoint is scored as an M1 model everywhere and known futures reach it through forecast_groups.
"""
from __future__ import annotations

import contextlib

from tideforge.model import ft3_model as FM

OPTIONS = {"known_attn": "off", "known_lookahead": None}


def options_of(cfg: dict) -> dict:
    """The model options recorded in a cfg (missing = off)."""
    return {k: cfg.get(k, v) for k, v in OPTIONS.items()}


def check_options(options: dict | None) -> dict:
    from tideforge.model.m1 import KNOWN_ATTN
    opts = dict(OPTIONS, **(options or {}))
    bad = sorted(set(opts) - set(OPTIONS))
    if bad:
        raise KeyError(f"unknown model option(s) {bad}; known: {sorted(OPTIONS)}")
    if opts["known_attn"] not in KNOWN_ATTN:
        raise NotImplementedError(f"model option known_attn={opts['known_attn']!r} is not built (known: {KNOWN_ATTN})")
    K = opts["known_lookahead"]
    if K is not None and (opts["known_attn"] == "off" or isinstance(K, bool) or not isinstance(K, int) or K < 1):
        raise ValueError(f"known_lookahead={K!r}: an int >= 1, and only with known_attn: mask")
    return opts


def build(cfg: dict, options: dict | None = None):
    """The model for cfg; options default to the ones the cfg records."""
    opts = check_options(options_of(cfg) if options is None else options)
    if opts["known_attn"] == "off":
        return FM.build_masked_model(cfg)
    from tideforge.model.m1 import build_m1
    return build_m1(cfg, opts["known_attn"], opts["known_lookahead"])


def n_params(model) -> int:
    return sum(p.numel() for p in model.parameters())


def load(path, device):
    """(model in eval mode, cfg, checkpoint), as third_party score_ft3.load_ft3 but built by build(cfg): strict, dropout 0."""
    import torch
    ck = torch.load(path, map_location=device, weights_only=False)
    cfg = dict(ck["cfg"])
    model = build(dict(cfg, dropout=0.0)).to(device)
    res = model.load_state_dict(ck["model"], strict=True)
    if res.missing_keys or res.unexpected_keys:
        raise SystemExit(f"{path}: state dict does not match the model: missing {res.missing_keys[:5]} "
                         f"unexpected {res.unexpected_keys[:5]}")
    return model.eval(), cfg, ck


@contextlib.contextmanager
def use_loader():
    """tidemark's scorers load checkpoints through score_ft3.load_ft3 (score_groups imports it at call time): swap in load()."""
    from tideforge.eval import thirdparty
    thirdparty.add_path()
    from tidemark.real import score_ft3
    saved = score_ft3.load_ft3
    score_ft3.load_ft3 = load
    try:
        yield
    finally:
        score_ft3.load_ft3 = saved
